From 81667e9c8ad827365f2d1e8b924caf062a19c593 Mon Sep 17 00:00:00 2001
From: Dan Carpenter <dan.carpenter@oracle.com>
Date: Mon, 3 Jul 2017 13:54:28 +0300
Subject: [PATCH] mtd: nand: mtk: release lock on error path

We only want to hold the lock on the success path, not this error path.

Fixes: 7ec4a37c5d71 ("mtd: nand: mediatek: add support for different MTK NAND FLASH Controller IP")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Boris Brezillon <boris.brezillon@free-electrons.com>

diff --git a/drivers/mtd/nand/mtk_ecc.c b/drivers/mtd/nand/mtk_ecc.c
index f38e2bb1953e..6c3a4aab0b48 100644
--- a/drivers/mtd/nand/mtk_ecc.c
+++ b/drivers/mtd/nand/mtk_ecc.c
@@ -273,8 +273,10 @@ int mtk_ecc_enable(struct mtk_ecc *ecc, struct mtk_ecc_config *config)
 	mtk_ecc_wait_idle(ecc, op);

 	ret = mtk_ecc_config(ecc, config);
-	if (ret)
+	if (ret) {
+		mutex_unlock(&ecc->lock);
 		return ret;
+	}

 	if (config->mode != ECC_NFI_MODE || op != ECC_ENCODE) {
 		init_completion(&ecc->done);
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from holding a mutex lock during an error condition in the `mtk_ecc_enable` function. If an error occurs while configuring the ECC, the lock is not released, leading to potential deadlocks or resource contention issues, as the lock remains held even when the operation fails.

        Commit message:
        mtd: nand: mtk: release lock on error path

We only want to hold the lock on the success path, not this error path.

Fixes: 7ec4a37c5d71 ("mtd: nand: mediatek: add support for different MTK NAND FLASH Controller IP")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Boris Brezillon <boris.brezillon@free-electrons.com>  

        Patch:

 int mtk_ecc_enable(struct mtk_ecc *ecc, struct mtk_ecc_config *config)
 {
 	enum mtk_ecc_operation op = config->op;
 	u16 reg_val;
 	int ret;

 	ret = mutex_lock_interruptible(&ecc->lock);
 	if (ret) {
 		dev_err(ecc->dev, "interrupted when attempting to lock\n");
 		return ret;
 	}

 	mtk_ecc_wait_idle(ecc, op);

 	ret = mtk_ecc_config(ecc, config);
-	if (ret)
+	if (ret) {
+		mutex_unlock(&ecc->lock);
 		return ret;
+	}

 	if (config->mode != ECC_NFI_MODE || op != ECC_ENCODE) {
 		init_completion(&ecc->done);
 		reg_val = ECC_IRQ_EN;
 		/*
 		 * For ECC_NFI_MODE, if ecc->caps->pg_irq_sel is 1, then it
 		 * means this chip can only generate one ecc irq during page
 		 * read / write. If is 0, generate one ecc irq each ecc step.
 		 */
 		if (ecc->caps->pg_irq_sel && config->mode == ECC_NFI_MODE)
 			reg_val |= ECC_PG_IRQ_SEL;
 		writew(reg_val, ecc->regs + ECC_IRQ_REG(op));
 	}

 	writew(ECC_OP_ENABLE, ecc->regs + ECC_CTL_REG(op));

 	return 0;
 }
 EXPORT_SYMBOL(mtk_ecc_enable);


